<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import jsQR from 'jsqr'
const props=defineProps<{disabled:boolean}>(),emit=defineEmits<{decoded:[code:string];reset:[]}>()
const video=ref<HTMLVideoElement|null>(null),input=ref<HTMLInputElement|null>(null),active=ref(false),starting=ref(false),reading=ref(false),message=ref(''),error=ref('')
let stream:MediaStream|null=null,timer:ReturnType<typeof setTimeout>|null=null,generation=0,disposed=false
function stop(){generation++;if(timer!==null)clearTimeout(timer);timer=null;stream?.getTracks().forEach(t=>t.stop());stream=null;if(video.value){video.value.pause();video.value.srcObject=null}active.value=false;starting.value=false;reading.value=false}
function available(g:number){return !disposed&&!props.disabled&&!document.hidden&&g===generation}
function decode(source:CanvasImageSource,width:number,height:number){const scale=Math.min(1,1280/Math.max(width,height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));const ctx=canvas.getContext('2d',{willReadFrequently:true});if(!ctx)throw new Error('此瀏覽器不支援圖片掃描，請改用手動輸入。');ctx.drawImage(source,0,0,canvas.width,canvas.height);const data=ctx.getImageData(0,0,canvas.width,canvas.height);return jsQR(data.data,data.width,data.height,{inversionAttempts:'attemptBoth'})?.data??null}
function accept(raw:string,g:number){if(!available(g))return;stop();if(!/^[A-Za-z0-9_-]{43}$/.test(raw)){error.value='QR 不是有效的票券碼，請使用此平台的電子票券。';return}message.value='已讀取票券碼。請按「核對票券」，確認場次後再明確驗票。';emit('decoded',raw)}
function frame(g:number){if(!available(g)){if(g===generation)stop();return}try{const v=video.value;if(v&&v.readyState>=2&&v.videoWidth>0){const raw=decode(v,v.videoWidth,v.videoHeight);if(raw!==null){accept(raw,g);return}}}catch{stop();error.value='無法讀取相機畫面，請改用圖片或手動輸入。';return}timer=setTimeout(()=>frame(g),160)}
async function start(){stop();error.value='';message.value='';if(props.disabled||disposed||document.hidden)return;emit('reset');if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){error.value='相機需要 HTTPS 與支援的瀏覽器；目前可上傳 QR 圖片或手動輸入。';return}const g=generation;starting.value=true;try{const acquired=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:640},height:{ideal:640}}});if(!available(g)){acquired.getTracks().forEach(t=>t.stop());return}stream=acquired;const v=video.value;if(!v)throw new Error();v.srcObject=acquired;await v.play();if(!available(g))return;starting.value=false;active.value=true;frame(g)}catch{if(!available(g))return;stop();error.value='相機無法開啟或權限未允許，請改用 QR 圖片或手動輸入。'}}
async function image(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(input.value)input.value.value='';stop();message.value='';error.value='';if(!file||props.disabled||disposed||document.hidden)return;emit('reset');if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){error.value='請選擇 5 MB 以內的 PNG、JPEG 或 WebP 圖片。';return}const g=generation;reading.value=true;let bitmap:ImageBitmap|null=null;try{bitmap=await createImageBitmap(file);if(!available(g))return;if(bitmap.width*bitmap.height>16_000_000)throw new Error('圖片超過 1600 萬像素，請縮小後再試。');const raw=decode(bitmap,bitmap.width,bitmap.height);if(raw===null){error.value='找不到清晰的 QR 碼，請重新拍攝或手動輸入。';return}accept(raw,g)}catch(e){if(available(g))error.value=e instanceof Error&&e.message.startsWith('圖片超過')?e.message:'圖片無法讀取，請改用其他圖片或手動輸入。'}finally{bitmap?.close();if(g===generation)reading.value=false}}
function leave(){stop()}
watch(()=>props.disabled,v=>{if(v){stop();message.value='';error.value=''}})
document.addEventListener('visibilitychange',leave);window.addEventListener('pagehide',leave)
onBeforeUnmount(()=>{disposed=true;stop();document.removeEventListener('visibilitychange',leave);window.removeEventListener('pagehide',leave)})
</script>
<template><section class="ticket-scanner" aria-label="掃描票券 QR"><p>QR 由此瀏覽器讀取，不上傳圖片；讀取後仍須核對與確認入場。</p><div class="scanner-controls"><button type="button" :disabled="disabled||starting||active||reading" @click="start">開啟相機掃描</button><button v-if="starting||active||reading" type="button" @click="stop">停止掃描</button><label>選擇 QR 圖片<input ref="input" type="file" accept="image/png,image/jpeg,image/webp" :disabled="disabled||starting||active||reading" @change="image" /></label></div><video ref="video" v-show="active" muted playsinline aria-label="相機掃描預覽"/><p v-if="starting" role="status">等待相機權限。可按停止取消。</p><p v-if="reading" role="status">正在讀取圖片。</p><p v-if="message" role="status">{{message}}</p><p v-if="error" class="notice error" role="alert">{{error}}</p></section></template>
<style scoped>.scanner-controls{display:flex;flex-wrap:wrap;gap:.75rem;align-items:center}.scanner-controls label{max-width:100%;min-width:0}.scanner-controls input{width:100%;max-width:300px}video{display:block;max-width:100%;width:480px;margin-top:1rem}.ticket-scanner{margin:1rem 0}</style>
